// Pending invitations live outside the fleet subcollection; they have no UID yet.
const normalizeFleetEmail=value=>String(value||'').trim().toLowerCase();
function memberEmail(member){return normalizeFleetEmail(member?.emailNormalized||member?.email);}
function visiblePendingMembers(){
  const registeredEmails=new Set(members.filter(m=>String(m.status||'ACTIVE').toUpperCase()==='ACTIVE').map(memberEmail).filter(Boolean));
  const seen=new Set();
  return pendingMembers.filter(invite=>{
    const state=String(invite.status||'PENDING').toUpperCase();
    if(state!=='PENDING')return false;
    const email=memberEmail(invite);
    if(!email||registeredEmails.has(email)||seen.has(email))return false;
    seen.add(email);
    return true;
  }).sort((a,b)=>memberEmail(a).localeCompare(memberEmail(b)));
}
function pendingMemberForScope(scope=fleetWorkspaceMemberScopeUid){
  if(!scope||!scope.startsWith('pending:'))return null;
  return visiblePendingMembers().find(invite=>'pending:'+invite.assignmentId===scope)||null;
}

