function playbackClock(ms){const seconds=Math.floor(ms/1000);return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
function showPlaybackAt(progress){
  const p=Math.max(0,Math.min(1,progress));
  routePlaybackLastProgress=p;
  for(const [id,points] of routePointsById){
    if(!selectedRouteIds.has(id)||points.length<2)continue;
    const marker=routePlaybackMarkers2d.get(id);
    if(marker)marker.setPosition(routePositionAtDistance(points,p*routeMetrics(points).total));
  }
  playbackSeek.value=String(Math.round(p*1000));
  playbackElapsed.textContent=playbackClock(p*playbackDuration());
  if(mapMode==='3d')update3dPlaybackPosition(p,true);
}
function updateRoutePlayButton(){
  const available=[...selectedRouteIds].some(id=>(routePointsById.get(id)||[]).length>1);
  const single3d=mapMode==='3d' && !!singlePlaybackRoute();
  if(mapMode==='3d' && !single3d && routePlaybackActive){
    routePlaybackOffset=0;routePlaybackActive=false;routePlaybackEpoch=0;
  }
  routePlayButton.disabled=!available||(mapMode==='3d'&&!single3d);
  routePlayButton.title=mapMode==='3d'&&!single3d?'Select exactly one route for 3D playback':'Play or stop selected routes';
  routePlayButton.textContent=routePlaybackActive?'■ Stop animation':'▶ Play routes';
  routePlayButton.setAttribute('aria-label',routePlaybackActive?'Stop route animation':'Start route animation');
  // Markers stay visible for selected routes, including before Play, while paused,
  // and after Stop/Finish. Only a change of selection removes them.
  for(const [id,marker] of routePlaybackMarkers2d){
    marker.setVisible(selectedRouteIds.has(id));
  }
  for(const [id,marker] of routePlaybackMarkers3d){
    if(mapMode==='3d'&&selectedRouteIds.has(id)){
      if(!marker.isConnected&&map3d)map3d.append(marker);
    }else if(marker.isConnected)marker.remove();
  }
  playbackTimeline.hidden=!available||(mapMode==='3d'&&!single3d);
  playbackTotal.textContent=playbackClock(playbackDuration());
  if(!routePlaybackActive){
    const progress=routeOverviewActive?routePlaybackLastProgress:routePlaybackOffset/playbackDuration();
    showPlaybackAt(progress);
  }
}
// When a regular route finishes or Stop is clicked, show every selected route
// in full on the Hybrid map, including GPS photos (the same overview as demo).
let routeOverviewActive=false;
let routeOverviewToken=0;
let regularPlaybackFinishing=false;
async function finishRegularRoutePlayback(reason='completed'){
  if(regularPlaybackFinishing)return;
  regularPlaybackFinishing=true;
  const token=++routeOverviewToken;
  routePlaybackActive=false;
  routePlaybackOffset=0;
  routePlaybackEpoch=0;
  routeOverviewActive=true;
  reset3dPlaybackCamera();
  updateRoutePlayButton();
  try{
    await switchMapMode('satellite'); // 'satellite' is Hybrid in this application.
    if(token!==routeOverviewToken||!map||mapMode!=='satellite')return;
    const points=[...routePointsById.entries()]
      .filter(([id])=>selectedRouteIds.has(id))
      .flatMap(([,pts])=>pts);
    if(!points.length)return;
    const bounds=new maps.LatLngBounds();
    points.forEach(point=>bounds.extend(point));
    for(const [id,photos] of routePhotosById){
      if(!selectedRouteIds.has(id))continue;
      for(const photo of photos){
        if(validPhotoCoords(photo))bounds.extend({
          lat:Number(photo.positionLatitude),lng:Number(photo.positionLongitude)
        });
      }
    }
    map.setMapTypeId('hybrid');
    // Keep each route playback marker at its last position in the full-route overview.
    renderPhotoMarkers();
    maps.event.trigger(map,'resize');

    // Smoothly zoom out, as the existing demo completion does (3.2 seconds).
    const targetCenter=bounds.getCenter();
    const ne=bounds.getNorthEast(),sw=bounds.getSouthWest();
    const mercatorY=lat=>Math.log(Math.tan(Math.PI/4+lat*Math.PI/360));
    const lngSpan=Math.max(1e-9,(ne.lng()-sw.lng()+360)%360||360);
    const latSpan=Math.max(1e-9,Math.abs(mercatorY(ne.lat())-mercatorY(sw.lat())));
    const width=Math.max(100,map.getDiv().clientWidth-110);
    const height=Math.max(100,map.getDiv().clientHeight-110);
    const zoomX=Math.log2(width*360/(256*lngSpan));
    const zoomY=Math.log2(height*2*Math.PI/(256*latSpan));
    const targetZoom=Math.max(1,Math.min(19,zoomX,zoomY));
    const startZoom=Math.min(19,targetZoom+3);
    map.moveCamera({center:targetCenter,zoom:startZoom});
    const started=performance.now();
    function zoomOut(now){
      if(token!==routeOverviewToken||!routeOverviewActive||mapMode!=='satellite'||routePlaybackActive)return;
      const t=Math.min(1,(now-started)/ROUTE_ZOOM_OUT_MS);
      const ease=t*t*(3-2*t);
      map.moveCamera({center:targetCenter,zoom:startZoom+(targetZoom-startZoom)*ease});
      if(t<1)requestAnimationFrame(zoomOut);
      else{
        map.moveCamera({center:targetCenter,zoom:targetZoom});
        renderPhotoMarkers();
        show('Animation '+reason+' · entire selected route'+(selectedRouteIds.size===1?'':'s')+' and GPS photos in Hybrid.');
      }
    }
    requestAnimationFrame(zoomOut);
  }catch(e){show('Could not show the completed route: '+(e.message||e));}
  finally{regularPlaybackFinishing=false;}
}

routePlayButton.addEventListener('click',()=>{
  if(routePlayButton.disabled||regularPlaybackFinishing)return;
  if(routePlaybackActive){finishRegularRoutePlayback('stopped');return;}
  routeOverviewActive=false;
  ++routeOverviewToken; // Cancel any old zoom-out when playback starts again.
  routePlaybackActive=true;
  routePlaybackEpoch=0;
  if(routePlaybackOffset>=playbackDuration())routePlaybackOffset=0;
  if(mapMode==='3d')reset3dPlaybackCamera();
  updateRoutePlayButton();
});
