    if(!selectedUids.has(uid)||(fleetWorkspaceMemberScopeUid&&uid!==fleetWorkspaceMemberScopeUid))continue;
    const target={lat:Number(loc.latitude??loc.lat),lng:Number(loc.longitude??loc.lon)};
    if(!Number.isFinite(target.lat)||!Number.isFinite(target.lng)||Math.abs(target.lat)>90||Math.abs(target.lng)>180)continue;
