      emptyInvite.querySelector('p').textContent='Your fleet is ready, but no routes have been shared yet. Use Track Reporter on Android to record and share a route with your fleet. You can also invite team members from the app.';
      ++sharedRouteStatsGeneration;sharedRouteStats.clear();
