      const old=routeOverlays.get(route.id);
      if(old){old.setMap(null);routeOverlays.delete(route.id);}
      const old3d=routeOverlays3d.get(route.id);
      if(old3d){old3d.remove();routeOverlays3d.delete(route.id);}
      clearRouteMarkers(route.id);
