function routeStartMillis(route){
  // The Firestore route document is an object; read its date field explicitly.
  const candidates = [
    route.startTimeMillis, route.sessionStartTimeMillis, route.startedAt,
    route.startTime, route.startTimestamp, route.createdAt,
    route.sharedAt, route.createdAtMillis
  ];
  for (const value of candidates) {
    const millis = locationMillis(value);
    if (millis > 0) return millis;
  }
  return 0;
}
function formatRouteDate(route){
  const millis = routeStartMillis(route);
  if(!millis) return 'Date unavailable';
  const d = new Date(millis);
  if(Number.isNaN(d.getTime())) return 'Date unavailable';
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
function visibleRoutes(){
  const queryText=String(document.getElementById('fleet-route-search')?.value||'').trim().toLocaleLowerCase();
  const timeFilter=String(document.getElementById('fleet-route-time-filter')?.value||'all');
  const now=Date.now(),day=86400000;
  return routes.filter(r=>{
    const uid=routeOwnerUid(r);
    const memberFilter=String(document.getElementById('fleet-route-member-filter')?.value||'all');
    if(!uid||(fleetWorkspaceMemberScopeUid&&uid!==fleetWorkspaceMemberScopeUid)||(memberFilter!=='all'&&uid!==memberFilter)||(routeFilter.value!=='all'&&r.status!=='ACTIVE'))return false;
    const start=routeStartMillis(r);
    if(timeFilter==='today' && (!start||new Date(start).toDateString()!==new Date(now).toDateString()))return false;
    if(timeFilter==='week' && (!start||now-start>7*day||start>now))return false;
    if(timeFilter==='month' && (!start||now-start>30*day||start>now))return false;
    const member=members.find(m=>m.uid===uid);
    const searchText=[formatRouteDate(r),member?.displayName,member?.email,r.name,r.routeName,r.sessionName].filter(Boolean).join(' ').toLocaleLowerCase();
    return !queryText||searchText.includes(queryText);
  });
}

// Shared route list: distance, elapsed time and photo count, also for unselected routes.
