  item.className='shared-route-metrics';
  item.dataset.routeMetricsId=route.id;
  const info=sharedRouteStats.get(route.id);
  item.textContent=sharedMetricText(route,info);
  if(info?.state==='error')item.title=info.error||'Could not retrieve photo count';
