function emailResultMessage(result){
  if(!result?.emailRequested)return 'Email notification not requested.';
  return result.emailSent?'Confirmation email sent.':`Saved, but email was NOT sent: ${result.emailError||'delivery failed'}`;
}
function setAdminFormFeedback(el,message,isError=false){
  el.textContent=message;
  el.classList.toggle('is-error',isError);
  el.classList.toggle('is-success',!!message&&!isError);
}
function setFormBusy(form,busy){
  for(const btn of form.querySelectorAll('button'))btn.disabled=busy;
  form.setAttribute('aria-busy',String(busy));
}
async function runFleetAdminAction(functionName,data){
  if(!currentFleetIsAdmin||!fleetId||!auth?.currentUser||!fleetAdminFunctions){
    throw new Error('Administrator access is required.');
  }
  const run=httpsCallable(fleetAdminFunctions,functionName);
  const response=await run({fleetId,...data});
  return response.data;
}
function resetWebAdminControls(){
  currentFleetIsAdmin=false;
  cancellingWorkOrderId=null;
  memberAdminControls.hidden=true;
  memberAddForm.hidden=true;
  woCreateForm.hidden=true;
  memberAddForm.reset();woCreateForm.reset();woCancelForm.reset();
  memberAddFeedback.textContent='';woCreateFeedback.textContent='';woCancelFeedback.textContent='';
  if(woCancelDialog.open)woCancelDialog.close();
}
function showWebAdminControls(isAdmin){
  currentFleetIsAdmin=!!isAdmin;
  memberAdminControls.hidden=!isAdmin;
  woCreateToggle.hidden=!isAdmin;
  if(!isAdmin){memberAddForm.hidden=true;woCreateForm.hidden=true;}
  renderWebAssignees();
}
function renderWebAssignees(){
  const sel=document.getElementById('web-wo-assignee');
  const previous=sel.value;
  sel.replaceChildren();
  const blank=document.createElement('option');blank.value='';blank.textContent='Select a member';sel.append(blank);
  const entries=new Map();
  for(const m of members){
    if(!m.uid||String(m.status||'ACTIVE').toUpperCase()!=='ACTIVE')continue;
    const email=memberEmail(m);
    const label=safeLabel(m.displayName||m.email||m.uid);
    entries.set(m.uid,email&&label.toLowerCase()!==email?`${label} (${email})`:label);
  }
  if(fleetOwnerUid && auth?.currentUser?.uid===fleetOwnerUid && !entries.has(fleetOwnerUid)){
    entries.set(fleetOwnerUid,auth.currentUser.displayName||auth.currentUser.email||'Fleet administrator');
  }
  // Pending invites have no Auth UID. Use a distinct selector key, never an
  // assignment UID. The submit handler converts it to email-only assignment.
  for(const invite of visiblePendingMembers()){
    const email=memberEmail(invite);
    if(!email)continue;
    const name=safeLabel(invite.displayName||'');
    const label=name&&name.toLowerCase()!==email?`${name} (${email})` : email;
    entries.set('pending:'+invite.assignmentId,`${label} — PENDING`);
  }
  for(const [key,label] of entries){
    const option=document.createElement('option');
    option.value=key;
    option.textContent=label;
    sel.append(option);
  }
  if(entries.has(previous))sel.value=previous;
}
function selectedWebWorkOrderAssignee(){
  const key=document.getElementById('web-wo-assignee').value;
  if(!key)throw new Error('Select a fleet member.');
  if(key.startsWith('pending:')){
    const invite=visiblePendingMembers().find(m=>'pending:'+m.assignmentId===key);
    if(!invite)throw new Error('This pending invitation is no longer available. Select another member.');
    return {assignedToUid:'',assignedToEmail:memberEmail(invite),isPending:true};
  }
  const active=members.find(m=>m.uid===key&&String(m.status||'ACTIVE').toUpperCase()==='ACTIVE');
  const isOwner=key===fleetOwnerUid&&auth?.currentUser?.uid===key;
  if(!active&&!isOwner)throw new Error('Selected member is no longer active. Select another member.');
  const email=memberEmail(active)||(isOwner?normalizeFleetEmail(auth.currentUser.email):'');
  return {assignedToUid:key,assignedToEmail:email,isPending:false};
}
