// Read-only Work Orders viewer for an authenticated fleet administrator.
// Routes are COPIES under fleets/{fleetId}/workOrders/{workOrderId}/routes/{routeId}
// (not shared_sessions). Their nested locations/photos reuse the fleet map renderer.
const WO_ROUTE_PREFIX='__work_order_route__:';
const woPanel=document.getElementById('fleet-work-orders-section');
const woList=document.getElementById('wo-list');
const woFilter=document.getElementById('wo-status-filter');
const woShowButton=document.getElementById('wo-show-routes');
const woFeedback=document.getElementById('wo-feedback');
let workOrders=[];
// Calendar is a read-only view of the already subscribed Work Orders collection.
// It does not require a Firestore index, new document fields, or another query.
let workOrderCalendarMode='week';
let workOrderCalendarAnchor=new Date();
let workOrderCalendarSelectedDate='';
let workOrderCalendarUnscheduled=false;
let workOrderDetailsOpenId=null;
let workOrderMapDetailId=null; // Compact details displayed alongside the GPS map.
const selectedWorkOrders=new Set();
const workOrderRouteKeys=new Set();
let workOrderUnsubscribe=null;
let workOrderLoadGeneration=0;
let workOrderViewerActive=false;
let workOrderLoading=false;
// Cached per-Work-Order route summaries. Displaying the list does not select or draw routes.
// Two concurrent workers keep the initial list responsive even for larger fleets.
const workOrderRouteStats=new Map();
let workOrderStatsGeneration=0;
function isWorkOrderRouteKey(id){return typeof id==='string'&&id.startsWith(WO_ROUTE_PREFIX);}
function workOrderRouteKey(workOrderId,routeId){return WO_ROUTE_PREFIX+encodeURIComponent(workOrderId)+':'+encodeURIComponent(routeId);}
function workOrderStatus(wo){return String(wo.status||'ASSIGNED').toUpperCase();}
function workOrderPriority(wo){
  const priority=String(wo.priority||'NORMAL').toUpperCase();
  return ['LOW','NORMAL','HIGH','URGENT'].includes(priority)?priority:'NORMAL';
}
function workOrderDueDate(wo){
  const due=String(wo.dueDate||'').trim();
  // Only ISO YYYY-MM-DD is supported, consistently with Android/Firestore.
  if(!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(due))return '';
  const [year,month,day]=due.split('-').map(Number);
  const actual=new Date(Date.UTC(year,month-1,day));
  if(actual.getUTCFullYear()!==year||actual.getUTCMonth()!==month-1||actual.getUTCDate()!==day)return '';
  return due;
}
function workOrderLocalToday(){
  const now=new Date();
  return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
}
function isWorkOrderOverdue(wo,today=workOrderLocalToday()){
  const due=workOrderDueDate(wo);
  return !!due && due<today && ['ASSIGNED','IN_PROGRESS'].includes(workOrderStatus(wo));
}
// Select the timestamp that actually belongs to the CURRENT Work Order status.
// Never describe createdAt as an assignment/completion date when the real field
// is missing. Firestore Timestamps, epoch milliseconds and ISO strings are supported.
function workOrderStatusDate(wo){
  const current=workOrderStatus(wo);
  const candidates={
    ASSIGNED:[['Assigned','assignedAt','assignedAtMillis','assignmentAt','assignedDate']],
    IN_PROGRESS:[['Reopened','reopenedAt'],['Started','startedAt','inProgressAt','startedAtMillis']],
    COMPLETED:[['Completed','completedAt','completedAtMillis','completionDate']],
    COMPLETE:[['Completed','completedAt','completedAtMillis','completionDate']],
    REJECTED:[['Rejected','rejectedAt','rejectedAtMillis']],
    CANCELLED:[['Cancelled','cancelledAt','canceledAt','cancelledAtMillis']],
    CANCELED:[['Cancelled','cancelledAt','canceledAt','cancelledAtMillis']],
    CREATED:[['Created','createdAt','createdAtMillis']]
  };
  const matches=[];
  for(const [label,...fields] of candidates[current]||[]){
    for(const field of fields){
      const ms=locationMillis(wo[field]);
      if(ms>0 && Number.isFinite(ms)){
        matches.push({label,ms});
        break;
      }
    }
  }
  // When a completed order has been reopened, use the latest relevant status date.
  if(matches.length)return matches.reduce((latest,item)=>item.ms>latest.ms?item:latest);
  // Backward compatibility: historical Work Orders may not have assignedAt.
  // Show their creation date honestly rather than misleadingly labelling it Assigned.
  for(const field of ['createdAt','createdAtMillis']){
    const ms=locationMillis(wo[field]);
    if(ms>0 && Number.isFinite(ms))return {label:'Created',ms};
  }
  return null;
}
function workOrderDisplayStatusDate(wo){
  const info=workOrderStatusDate(wo);
  if(!info)return 'Status date unavailable';
  const date=new Intl.DateTimeFormat('en-GB',{
    day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'
  }).format(new Date(info.ms));
  return `${info.label}: ${date}`;
}

// Display distance, elapsed recording time and number of photos for EACH route
// attached to a Work Order. Prefer cached route-document metrics when provided.
// For historical route documents without metrics, derive distance/time from the
// actual GPS locations and count photos server-side (without downloading photos).
function firstUsableMetric(object,fields){
  for(const field of fields){
    const raw=object?.[field];
    if(raw===null||raw===undefined||raw==='')continue;
    const value=Number(raw);
    if(Number.isFinite(value)&&value>=0)return value;
  }
  return null;
}
function workOrderDistanceMetric(route){
  const meters=firstUsableMetric(route,[
    'distanceMeters','totalDistanceMeters','routeDistanceMeters','recordedDistanceMeters',
    'sessionDistanceMeters','distanceInMeters','totalDistanceInMeters'
  ]);
  if(meters!==null)return meters;
  const km=firstUsableMetric(route,['distanceKm','totalDistanceKm','routeDistanceKm','sessionDistanceKm']);
  return km!==null?km*1000:null;
}
function workOrderDurationMetric(route){
  const ms=firstUsableMetric(route,[
    'durationMillis','durationMs','totalDurationMillis','routeDurationMillis',
    'sessionDurationMillis','elapsedTimeMillis','elapsedMillis'
  ]);
  if(ms!==null)return ms;
  const secs=firstUsableMetric(route,['durationSeconds','totalDurationSeconds','elapsedSeconds']);
  if(secs!==null)return secs*1000;
  const start=routeStartMillis(route);
  const endFields=['endTimeMillis','sessionEndTimeMillis','finishedAt','endedAt','endTime'];
  for(const field of endFields){
    const end=locationMillis(route[field]);
    if(start&&end>=start)return end-start;
  }
  return null;
}
function formatWorkOrderDistance(meters){
  return meters===null?'—':meters<1000?`${Math.round(meters)} m`:`${(meters/1000).toFixed(2)} km`;
}
function formatWorkOrderDuration(ms){
  if(ms===null)return '—';
  const sec=Math.max(0,Math.round(ms/1000));
  const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;
  return h?`${h}h ${String(m).padStart(2,'0')}m`:`${m}m ${String(s).padStart(2,'0')}s`;
}
function gpsDistanceMeters(points){
  const rad=Math.PI/180,R=6371000;
  let sum=0;
  for(let i=1;i<points.length;i++){
    const a=points[i-1],b=points[i];
    const dLat=(b.lat-a.lat)*rad;
    const dLon=longitudeDelta(a.lng,b.lng)*rad;
    const sinLat=Math.sin(dLat/2),sinLon=Math.sin(dLon/2);
    const hav=sinLat*sinLat+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*sinLon*sinLon;
    sum+=R*2*Math.atan2(Math.sqrt(Math.max(0,hav)),Math.sqrt(Math.max(0,1-hav)));
  }
  return sum;
}
async function fetchWorkOrderRouteSummary(orderId,routeDoc,authorizedFleetId,identity,generation){
  const routeId=routeDoc.id;
  const route=routeDoc.data();
  if(String(route.status||'').trim().toUpperCase()==='DELETING')return null;
  const routeRef=doc(db,'fleets',authorizedFleetId,'workOrders',orderId,'routes',routeId);
  let distance=workOrderDistanceMetric(route);
  let duration=workOrderDurationMetric(route);
  let photoCount=firstUsableMetric(route,['photoCount','photosCount','numberOfPhotos','totalPhotoCount']);
  // Do not download every GPS point for table statistics. Full geometry is
  // fetched only when an administrator requests GPS evidence on the map.
  const existing=routePointsById.get(workOrderRouteKey(orderId,routeId));
  if(existing&&existing.length&&distance===null)distance=gpsDistanceMeters(existing);
  if(photoCount===null){
    const photosRef=collection(routeRef,'photos');
    try{
      // Aggregate query avoids transferring all photo documents just for a count.
      photoCount=(await getCountFromServer(photosRef)).data().count;
    }catch(error){
      console.debug('Work Order photo count unavailable:',error.message);
    }
  }
  if(generation!==workOrderStatsGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return null;
  const started=routeStartMillis(route);
  return {
    id:routeId,
    title:route.routeName||route.sessionName||route.title||route.name||'',
    started,
    distance,duration,photoCount,
    status:String(route.status||'').toUpperCase()
  };
}
function showWorkOrderRouteSummary(detail,wo){
  const wrap=document.createElement('div');wrap.className='wo-route-list';
  const snapshot=workOrderRouteStats.get(wo.id);
  if(!snapshot||snapshot.state==='loading'){
    const loading=document.createElement('span');loading.className='wo-route-loading';
    const spinner=document.createElement('span');spinner.className='fleet-route-spinner';
    loading.append(spinner,document.createTextNode('Loading route statistics…'));
    wrap.append(loading);
  }else if(snapshot.state==='error'){
    const err=document.createElement('span');err.className='wo-route-note';
    err.textContent='Route statistics unavailable';
    err.title=snapshot.error||'';wrap.append(err);
  }else if(!snapshot.routes.length){
    const empty=document.createElement('span');empty.className='wo-route-note';
    empty.textContent='No linked routes';wrap.append(empty);
  }else{
    for(let i=0;i<snapshot.routes.length;i++){
      const route=snapshot.routes[i];
      const row=document.createElement('div');row.className='wo-route-row';
      const name=document.createElement('span');name.className='wo-route-name';
      name.textContent=route.title||`Route ${i+1}`;
      const measures=document.createElement('span');measures.className='wo-route-measures';
      const pieces=[
        `Distance: ${formatWorkOrderDistance(route.distance)}`,
        `Duration: ${formatWorkOrderDuration(route.duration)}`,
        `Photos: ${route.photoCount===null?'—':route.photoCount}`
      ];
      measures.textContent=pieces.join(' · ');
      row.append(name,measures);wrap.append(row);
    }
  }
  detail.append(wrap);
}
// Batch load without changing checkbox selection or auto-adding anything to the map.
async function loadWorkOrderRouteStats(authorizedFleetId,identity,generation,priorityIds=[]){
  // Details may be opened directly from the calendar for a day that is not
  // currently included in the agenda's status filter.
  const orderIds=[...new Set([...priorityIds,...shownWorkOrders().map(order=>order.id)])]
    .filter(id=>workOrders.some(order=>order.id===id)&&!workOrderRouteStats.has(id));
  let cursor=0;
  const worker=async()=>{
    while(cursor<orderIds.length){
      const orderId=orderIds[cursor++];
      if(generation!==workOrderStatsGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
      if(workOrderRouteStats.has(orderId))continue;
      workOrderRouteStats.set(orderId,{state:'loading',routes:[]});
      renderWorkOrders();
      refreshOpenWorkOrderRouteSummary(orderId);
      try{
        const routesSnap=await getDocs(collection(db,'fleets',authorizedFleetId,'workOrders',orderId,'routes'));
        if(generation!==workOrderStatsGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
        const entries=[];
        for(const routeDoc of routesSnap.docs){
          const stats=await fetchWorkOrderRouteSummary(orderId,routeDoc,authorizedFleetId,identity,generation);
          if(!stats){
            if(generation!==workOrderStatsGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
            continue;
          }
          entries.push(stats);
        }
        workOrderRouteStats.set(orderId,{state:'ready',routes:entries});
      }catch(error){
        if(generation!==workOrderStatsGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
        workOrderRouteStats.set(orderId,{state:'error',routes:[],error:error.message||String(error)});
      }
      renderWorkOrders();
      refreshOpenWorkOrderRouteSummary(orderId);
    }
  };
  await Promise.all([worker(),worker()]);
}
function scheduleWorkOrderRouteStats(priorityIds=[]){
  if(!db||!fleetId||!auth?.currentUser||woPanel.hidden||fleetWorkspaceView!=='orders')return;
  const generation=++workOrderStatsGeneration;
  // Preserve successfully loaded results; reload only Work Orders that changed.
  for(const [id,value] of workOrderRouteStats){if(value.state==='loading')workOrderRouteStats.delete(id);}
  loadWorkOrderRouteStats(fleetId,auth.currentUser.uid,generation,priorityIds).catch(console.error);
}
function setWorkOrderFeedback(message,kind=''){
  woFeedback.className='wo-feedback'+(kind?' '+kind:'');woFeedback.textContent=message;
}

function workOrderSearchMatches(wo,searchText){
  if(!searchText)return true;
  const assignee=members.find(m=>m.uid===wo.assignedToUid);
  const searchable=[wo.workOrderNumber,wo.siteName,wo.clientName,wo.description,wo.assignedToEmail,
    assignee?.email,assignee?.displayName].filter(Boolean).join(' ').toLocaleLowerCase();
  return searchable.includes(searchText);
}
function visibleCalendarWorkOrders(){
  const search=String(document.getElementById('fleet-orders-search')?.value||'').trim().toLocaleLowerCase();
  // Calendar deliberately shows every current status even when the agenda filter
  // is "Completed". Selecting a day automatically switches the agenda to ALL.
  return workOrders.filter(wo=>workOrderMatchesMemberScope(wo)&&workOrderSearchMatches(wo,search));
}
function shownWorkOrders(){
  const today=workOrderLocalToday();
  const searchText=String(document.getElementById('fleet-orders-search')?.value||'').trim().toLocaleLowerCase();
  const filtered=workOrders.filter(wo=>{
    const statusMatch=woFilter.value==='ALL'||
      (woFilter.value==='OVERDUE'?isWorkOrderOverdue(wo,today):workOrderStatus(wo)===woFilter.value);
    const due=workOrderDueDate(wo);
    const dateMatch=workOrderCalendarUnscheduled?!due:
      (!workOrderCalendarSelectedDate||due===workOrderCalendarSelectedDate);
    return workOrderMatchesMemberScope(wo)&&statusMatch&&dateMatch&&workOrderSearchMatches(wo,searchText);
  });
  const mode=document.getElementById('wo-sort-order')?.value||'due-asc';
  const priorityRank={URGENT:4,HIGH:3,NORMAL:2,MEDIUM:2,LOW:1};
  const dateMs=(value)=>locationMillis(value)||0;
  return filtered.sort((a,b)=>{
    let comparison=0;
    if(mode.startsWith('due-')){
      const da=workOrderDueDate(a),db=workOrderDueDate(b);
      comparison=!da&&!db?0:!da?1:!db?-1:mode==='due-asc'?da.localeCompare(db):db.localeCompare(da);
    }else if(mode==='created-desc')comparison=dateMs(b.createdAt)-dateMs(a.createdAt);
    else if(mode==='created-asc')comparison=dateMs(a.createdAt)-dateMs(b.createdAt);
    else if(mode==='completed-desc')comparison=dateMs(b.completedAt)-dateMs(a.completedAt);
    else if(mode==='completed-asc')comparison=dateMs(a.completedAt)-dateMs(b.completedAt);
    else if(mode==='priority-desc')comparison=(priorityRank[workOrderPriority(b)]||0)-(priorityRank[workOrderPriority(a)]||0);
    else if(mode==='name-asc')comparison=String(a.workOrderNumber||a.siteName||a.id).localeCompare(String(b.workOrderNumber||b.siteName||b.id),undefined,{numeric:true});
    return comparison||dateMs(b.createdAt)-dateMs(a.createdAt)||String(a.id).localeCompare(String(b.id));
  });
}
function fleetCalendarKey(date){
  return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
}
function fleetCalendarDate(value){
  const [y,m,d]=value.split('-').map(Number);
  return new Date(y,m-1,d,12);
}
function fleetCalendarShift(date,days){
  const next=new Date(date.getFullYear(),date.getMonth(),date.getDate(),12);
  next.setDate(next.getDate()+days);
  return next;
}
function fleetCalendarWeekStart(date){
  return fleetCalendarShift(date,-((date.getDay()+6)%7));
}
function fleetCalendarDisplay(date,opts){return new Intl.DateTimeFormat('en-GB',opts).format(date);}
function fleetWorkOrderColorStatus(status){
  return ['CREATED','ASSIGNED','IN_PROGRESS','COMPLETED','COMPLETE','REJECTED','CANCELLED','CANCELED'].includes(status)?status:'OTHER';
}
function chooseFleetCalendarDate(dateKey){
  workOrderCalendarSelectedDate=dateKey;
  workOrderCalendarUnscheduled=false;
  woFilter.value='ALL';
  renderWorkOrders();scheduleWorkOrderRouteStats();
  // On phones the calendar is a date selector; show the complete agenda below.
  if(window.matchMedia('(max-width:760px)').matches){
    requestAnimationFrame(()=>{
      const agenda=document.getElementById('fleet-orders-slot');
      if(agenda){
        const top=agenda.getBoundingClientRect().top+window.scrollY-76;
        window.scrollTo({top:Math.max(0,top),behavior:'smooth'});
      }
    });
  }
}
function renderWorkOrderCalendar(){
  if(!fleetWorkspaceBuilt)return;
  const calendar=document.getElementById('fleet-order-calendar');
  if(!calendar)return;
  calendar.dataset.mode=workOrderCalendarMode;
  const grid=document.getElementById('fleet-cal-grid');
  grid.replaceChildren();
  const anchor=new Date(workOrderCalendarAnchor.getFullYear(),workOrderCalendarAnchor.getMonth(),workOrderCalendarAnchor.getDate(),12);
  const isMonth=workOrderCalendarMode==='month';
  const first=isMonth?fleetCalendarWeekStart(new Date(anchor.getFullYear(),anchor.getMonth(),1,12)):fleetCalendarWeekStart(anchor);
  const days=isMonth?Math.ceil(((new Date(anchor.getFullYear(),anchor.getMonth()+1,0).getDate())+((new Date(anchor.getFullYear(),anchor.getMonth(),1).getDay()+6)%7))/7)*7:7;
  const last=fleetCalendarShift(first,days-1);
  const title=isMonth?fleetCalendarDisplay(anchor,{month:'long',year:'numeric'}):
    `${fleetCalendarDisplay(first,{day:'numeric',month:'short'})} – ${fleetCalendarDisplay(last,{day:'numeric',month:'short',year:'numeric'})}`;
  document.getElementById('fleet-cal-title').textContent=title;
  const orders=visibleCalendarWorkOrders();
  const byDate=new Map();
  for(const wo of orders){
    const due=workOrderDueDate(wo);
    if(!due)continue;
    if(!byDate.has(due))byDate.set(due,[]);
    byDate.get(due).push(wo);
  }
  let count=0;
  for(let i=0;i<days;i++){
    const d=fleetCalendarShift(first,i);
    if((!isMonth||d.getMonth()===anchor.getMonth()))count+=(byDate.get(fleetCalendarKey(d))||[]).length;
  }
  document.getElementById('fleet-cal-count').textContent=`${count} scheduled`;
  const today=workOrderLocalToday();
  for(const weekday of ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']){
    const heading=document.createElement('div');heading.className='fleet-cal-weekday';heading.textContent=weekday;grid.append(heading);
  }
  for(let i=0;i<days;i++){
    const d=fleetCalendarShift(first,i),dateKey=fleetCalendarKey(d);
    const outside=isMonth&&d.getMonth()!==anchor.getMonth();
    const cell=document.createElement('div');cell.className='fleet-cal-cell'+(dateKey===today?' is-today':'')+
      (dateKey===workOrderCalendarSelectedDate&&!workOrderCalendarUnscheduled?' is-selected':'')+(outside?' is-outside':'');
    const dateBtn=document.createElement('button');dateBtn.type='button';dateBtn.className='fleet-cal-day'+(dateKey===today?' is-today-date':'');
    const day=document.createElement('span');day.textContent=String(d.getDate());
    const dayCount=document.createElement('span');const dayOrders=byDate.get(dateKey)||[];
    dayCount.textContent=dayOrders.length?String(dayOrders.length):'';
    dateBtn.append(day,dayCount);
    dateBtn.title=`Show all Work Orders due on ${fleetCalendarDisplay(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}`;
    dateBtn.setAttribute('aria-label',dateBtn.title);
    dateBtn.addEventListener('click',()=>{workOrderCalendarAnchor=d;chooseFleetCalendarDate(dateKey);});
    cell.append(dateBtn);
    const events=document.createElement('div');events.className='fleet-cal-events';
    // Compact but still directly clickable Work Order chips. On narrow screens,
    // their labels collapse to colored bars; aria-label retains the full name.
    const eventLimit=isMonth?2:3;
    for(const wo of dayOrders.slice(0,eventLimit)){
      const status=workOrderStatus(wo),chip=document.createElement('button');
      chip.type='button';chip.className='fleet-cal-event fleet-wo-status-'+fleetWorkOrderColorStatus(status)+(isWorkOrderOverdue(wo,today)?' is-overdue':'');
      const titleText=String(wo.workOrderNumber||wo.siteName||wo.clientName||wo.id);
      chip.textContent=titleText;
      chip.title=`${titleText} · ${status.replace(/_/g,' ')}${isWorkOrderOverdue(wo,today)?' · OVERDUE':''}`;
      chip.setAttribute('aria-label','Details: '+chip.title);
      chip.addEventListener('click',()=>openWorkOrderEvidence(wo));
      events.append(chip);
    }
    if(dayOrders.length>eventLimit){
      const more=document.createElement('button');more.type='button';more.className='fleet-cal-more';
      more.textContent=`+${dayOrders.length-eventLimit} more`;
      more.setAttribute('aria-label',`Show all ${dayOrders.length} Work Orders for ${dateKey}`);
      more.addEventListener('click',()=>{workOrderCalendarAnchor=d;chooseFleetCalendarDate(dateKey);});
      events.append(more);
    }
    cell.append(events);grid.append(cell);
  }
  const legend=document.getElementById('fleet-cal-legend');legend.replaceChildren();
  const legendItems=[['ASSIGNED','Assigned'],['IN_PROGRESS','In progress'],['COMPLETED','Completed'],
    ['REJECTED','Rejected'],['CANCELLED','Cancelled'],['CREATED','Created']];
  for(const [status,name] of legendItems){
    const item=document.createElement('span');item.className='fleet-cal-legend-item fleet-wo-status-'+status;
    const swatch=document.createElement('i');swatch.className='fleet-cal-swatch';swatch.setAttribute('aria-hidden','true');
    item.append(swatch,document.createTextNode(name));legend.append(item);
  }
  const overdue=document.createElement('span');overdue.className='fleet-cal-legend-item';
  const os=document.createElement('i');os.className='fleet-cal-swatch is-overdue';os.setAttribute('aria-hidden','true');
  overdue.append(os,document.createTextNode('Overdue'));legend.append(overdue);
  for(const [key,active] of [['week',!isMonth],['month',isMonth]]){
    const button=document.getElementById('fleet-cal-'+key);
    button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active));
  }
  const unscheduled=document.getElementById('fleet-cal-unscheduled');
  unscheduled.textContent=`No due date (${orders.filter(wo=>!workOrderDueDate(wo)).length})`;
  unscheduled.classList.toggle('is-active',workOrderCalendarUnscheduled);
  const all=document.getElementById('fleet-cal-clear');
  all.classList.toggle('is-active',!workOrderCalendarSelectedDate&&!workOrderCalendarUnscheduled&&woFilter.value==='ALL');
}
function setupWorkOrderCalendar(){
  const prev=document.getElementById('fleet-cal-prev'),next=document.getElementById('fleet-cal-next');
  const navigate=(direction)=>{
    if(workOrderCalendarMode==='month')workOrderCalendarAnchor=new Date(workOrderCalendarAnchor.getFullYear(),workOrderCalendarAnchor.getMonth()+direction,1,12);
    else workOrderCalendarAnchor=fleetCalendarShift(workOrderCalendarAnchor,direction*7);
    workOrderCalendarSelectedDate='';workOrderCalendarUnscheduled=false;
    renderWorkOrders();scheduleWorkOrderRouteStats();
  };
  prev.addEventListener('click',()=>navigate(-1));next.addEventListener('click',()=>navigate(1));
  document.getElementById('fleet-cal-today').addEventListener('click',()=>{
    workOrderCalendarAnchor=new Date();chooseFleetCalendarDate(workOrderLocalToday());
  });
  for(const mode of ['week','month'])document.getElementById('fleet-cal-'+mode).addEventListener('click',()=>{
    workOrderCalendarMode=mode;
    renderWorkOrders();
  });
  document.getElementById('fleet-cal-unscheduled').addEventListener('click',()=>{
    workOrderCalendarUnscheduled=true;workOrderCalendarSelectedDate='';woFilter.value='ALL';
    renderWorkOrders();scheduleWorkOrderRouteStats();
  });
  document.getElementById('fleet-cal-clear').addEventListener('click',()=>{
    workOrderCalendarUnscheduled=false;workOrderCalendarSelectedDate='';woFilter.value='ALL';
    renderWorkOrders();scheduleWorkOrderRouteStats();
  });
}

// Map and gallery explanations follow the current viewer, without changing
// public-demo content or the Shared Routes browsing controls.
function updateMapContextCaption(){
  const shared=document.getElementById('fleet-map-caption-member');
  const orders=document.getElementById('fleet-map-caption-work-orders');
  const title=document.getElementById('fleet-photo-gallery-title');
  const showingOrders=workOrderViewerActive && workOrderRouteKeys.size>0;
  if(shared)shared.hidden=showingOrders;
  if(orders)orders.hidden=!showingOrders;
  if(title)title.textContent=showingOrders?'Work Order photos':'Route photos';
}

// Per-Work-Order progress persists even when Firestore causes a list re-render.
const workOrderPdfProgress=new Map();
function updateWorkOrderPdfProgress(id,percent,message,busy=true){
  workOrderPdfProgress.set(id,{percent,message,busy});
  document.querySelectorAll('[data-work-order-pdf-id]').forEach(button=>{
    if(button.dataset.workOrderPdfId!==String(id))return;
    button.disabled=busy;
    button.classList.toggle('wo-pdf-busy',busy);
    const label=button.querySelector('.wo-pdf-label');
    if(label)label.textContent=message;
    const bar=button.querySelector('.wo-pdf-progress-fill');
    if(bar)bar.style.width=(Number.isFinite(percent)?Math.max(0,Math.min(100,percent)):0)+'%';
    const progress=button.querySelector('.wo-pdf-progress');
    if(progress){progress.hidden=!busy;progress.classList.toggle('is-indeterminate',!Number.isFinite(percent));}
  });
}
// Keep the Work Orders page intact. PDF preview opens in a separate tab.
const workOrderPdfObjectUrls=[];
function openDownloadedWorkOrderPdf(blobUrl,wo){
  const tab=window.open(blobUrl,'_blank');
  if(tab){
    try{tab.opener=null;}catch(_e){}
    return true;
  }
  // Browser may block a tab opened after an asynchronous download.
  // Give the user an explicit click target, which is not popup-blocked.
  document.querySelectorAll('[data-work-order-pdf-id]').forEach(button=>{
    if(button.dataset.workOrderPdfId!==String(wo.id))return;
    let openButton=button.parentElement.querySelector('.wo-pdf-open');
    if(!openButton){
      openButton=document.createElement('button');
      openButton.type='button';openButton.className='fleet-quiet-btn wo-pdf-open';
      openButton.textContent='Open downloaded PDF';
      openButton.addEventListener('click',event=>{
        event.preventDefault();event.stopPropagation();
        const t=window.open(blobUrl,'_blank');
        if(t){try{t.opener=null;}catch(_e){}}
      });
      button.insertAdjacentElement('afterend',openButton);
    }
  });
  return false;
}
async function downloadCompletedWorkOrderPdf(wo,button){
  if(workOrderStatus(wo)!=='COMPLETED'||workOrderPdfProgress.get(wo.id)?.busy)return;
  document.querySelectorAll('[data-work-order-pdf-id]').forEach(el=>{if(el.dataset.workOrderPdfId===String(wo.id))el.parentElement.querySelectorAll('.wo-pdf-error').forEach(x=>x.remove());});
  updateWorkOrderPdfProgress(wo.id,NaN,'Connecting…');
  try{
    if(!db||!storage||!fleetId)throw new Error('Firebase is not connected.');
    const snap=await getDoc(doc(db,'fleets',fleetId,'workOrders',wo.id));
    if(!snap.exists())throw new Error('Work Order not found.');
    const current=snap.data();
    if(String(current.status||'').toUpperCase()!=='COMPLETED')throw new Error('Work Order is no longer completed.');
    const state=String(current.reportStatus||'').toUpperCase();
    if(state!=='READY')throw new Error('Report is not ready (status: '+(state||'not published')+').');
    const path=String(current.reportStoragePath||'').trim();
    if(!path.startsWith(`fleets/${fleetId}/workOrders/${wo.id}/reports/`)||!path.toLowerCase().endsWith('.pdf'))
      throw new Error('Invalid or missing reportStoragePath.');
    updateWorkOrderPdfProgress(wo.id,NaN,'Getting PDF…');
    const url=await getDownloadURL(storageRef(storage,path));
    let response;
    try { response=await fetch(url); } catch(fetchError) {
      // Without Firebase Storage CORS, JavaScript cannot read the bytes and
      // therefore cannot reliably trigger both a local download and a PDF preview.
      throw new Error('Browser cannot download PDF from Firebase Storage (CORS/network). Configure Storage CORS for https://trackreporter.com. '+(fetchError.message||fetchError));
    }
    if(!response.ok)throw new Error('PDF download failed (HTTP '+response.status+').');
    const total=Number(response.headers.get('content-length'))||0;
    let blob;
    if(response.body){
      const reader=response.body.getReader(),parts=[];let loaded=0;
      while(true){
        const {done,value}=await reader.read();if(done)break;
        parts.push(value);loaded+=value.byteLength;
        updateWorkOrderPdfProgress(wo.id,total?Math.round(loaded*100/total):NaN,total?`Downloading ${Math.min(100,Math.round(loaded*100/total))}%`:`Downloading ${Math.round(loaded/1024)} KB`);
      }
      blob=new Blob(parts,{type:'application/pdf'});
    }else blob=await response.blob();
    updateWorkOrderPdfProgress(wo.id,100,'Saving PDF…');
    const blobUrl=URL.createObjectURL(blob);
    const link=document.createElement('a');link.href=blobUrl;
    link.download=`work-order-${String(wo.workOrderNumber||wo.id).replace(/[^a-z0-9_-]/gi,'_')}.pdf`;
    document.body.append(link);link.click();link.remove();
    // Reuse the downloaded Blob; do not fetch from Firebase a second time.
    workOrderPdfObjectUrls.push(blobUrl);
    // Keep recent URLs alive for the new tab, but avoid unbounded memory growth.
    while(workOrderPdfObjectUrls.length>5)URL.revokeObjectURL(workOrderPdfObjectUrls.shift());
    const opened=openDownloadedWorkOrderPdf(blobUrl,wo);
    updateWorkOrderPdfProgress(wo.id,100,opened?'Downloaded':'Downloaded · Open PDF',false);
  }catch(error){
    console.error('Work Order PDF download failed',error);
    const message='PDF error: '+(error.message||error);
    updateWorkOrderPdfProgress(wo.id,0,'Retry PDF',false);
    document.querySelectorAll('[data-work-order-pdf-id]').forEach(el=>{
      if(el.dataset.workOrderPdfId===String(wo.id)){
        el.title=message;
        let errorLabel=el.parentElement.querySelector('.wo-pdf-error');
        if(!errorLabel){errorLabel=document.createElement('small');errorLabel.className='wo-pdf-error';errorLabel.style.cssText='display:block;color:#fda4af;font-size:11px;max-width:260px;overflow-wrap:anywhere;margin-top:5px';el.insertAdjacentElement('afterend',errorLabel);}
        errorLabel.textContent=message;
      }
    });
    setWorkOrderFeedback(message,'error');
  }
}
function appendCompletedWorkOrderPdfAction(parent,wo){
  if(workOrderStatus(wo)!=='COMPLETED')return;
  const state=workOrderPdfProgress.get(wo.id);
  const button=document.createElement('button');button.type='button';
  button.className='fleet-quiet-btn wo-pdf-action'+(state?.busy?' wo-pdf-busy':'');
  button.dataset.workOrderPdfId=String(wo.id);
  button.disabled=!!state?.busy;
  const label=document.createElement('span');label.className='wo-pdf-label';
  label.textContent=state?.message||'Download PDF';
  const progress=document.createElement('span');progress.className='wo-pdf-progress'+(!Number.isFinite(state?.percent)?' is-indeterminate':'');
  progress.hidden=!state?.busy;
  const fill=document.createElement('span');fill.className='wo-pdf-progress-fill';
  fill.style.width=(Number.isFinite(state?.percent)?state.percent:0)+'%';progress.append(fill);
  button.append(label,progress);
  button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();downloadCompletedWorkOrderPdf(wo,button);});
  parent.append(button);
}
function renderWorkOrders(){
  woList.replaceChildren();
  const today=workOrderLocalToday();
  const overdueCount=workOrders.filter(wo=>workOrderMatchesMemberScope(wo)&&isWorkOrderOverdue(wo,today)).length;
  const overdueOption=woFilter.querySelector('option[value="OVERDUE"]');
  if(overdueOption)overdueOption.textContent=`Overdue (${overdueCount})`;
  const shown=shownWorkOrders();
  renderWorkOrderCalendar();
  if(!shown.length){
    const p=document.createElement('p');
    p.textContent=workOrderCalendarSelectedDate
      ?`No Work Orders due on ${workOrderCalendarSelectedDate} with the selected filters.`
      :workOrderCalendarUnscheduled
      ?'No Work Orders without a due date with the selected filters.'
      :fleetWorkspaceMemberScopeUid
      ?'No Work Orders for the selected member and filters.'
      :workOrders.length
      ?(woFilter.value==='OVERDUE'?'No overdue Work Orders.':'No Work Orders with this status.')
      :'No Work Orders in this fleet.';
    woList.append(p);
  }
  const groupByDue=(document.getElementById('wo-sort-order')?.value||'due-asc').startsWith('due-');
  let lastDueGroup=null;
  const groupTotals=new Map();
  for(const wo of shown){const key=workOrderDueDate(wo)||'unscheduled';groupTotals.set(key,(groupTotals.get(key)||0)+1);}
  for(const wo of shown){
    const dueGroup=workOrderDueDate(wo)||'unscheduled';
    if(groupByDue&&dueGroup!==lastDueGroup){
      lastDueGroup=dueGroup;
      const heading=document.createElement('div');heading.className='fleet-wo-agenda-heading';
      const label=document.createElement('span');
      label.textContent=dueGroup==='unscheduled'?'No due date':
        `Due · ${fleetCalendarDisplay(fleetCalendarDate(dueGroup),{weekday:'short',day:'numeric',month:'long',year:'numeric'})}`;
      const total=document.createElement('span');total.textContent=`${groupTotals.get(dueGroup)} order${groupTotals.get(dueGroup)===1?'':'s'}`;
      heading.append(label,total);woList.append(heading);
    }
    const label=document.createElement('div');label.className='wo-card fleet-wo-status-'+fleetWorkOrderColorStatus(workOrderStatus(wo))+(selectedWorkOrders.has(wo.id)?' is-selected':'')+(isWorkOrderOverdue(wo,today)?' is-overdue':'');
    label.tabIndex=0;label.setAttribute('role','button');
    label.setAttribute('aria-label','Show details, GPS routes and photos for Work Order '+String(wo.workOrderNumber||wo.id));
    label.title='Show details and attached GPS routes on the map';
    label.addEventListener('click',event=>{
      if(event.target.closest('input,button,a'))return;
      openWorkOrderEvidence(wo);
    });
    label.addEventListener('keydown',event=>{
      if(event.target!==label||!['Enter',' '].includes(event.key))return;
      event.preventDefault();openWorkOrderEvidence(wo);
    });
    const cb=document.createElement('input');cb.type='checkbox';cb.checked=selectedWorkOrders.has(wo.id);
    cb.setAttribute('aria-label','Select Work Order '+String(wo.workOrderNumber||wo.id)+' for multi-order map view');
    cb.addEventListener('click',event=>event.stopPropagation());
    cb.addEventListener('change',()=>{
      if(cb.checked)selectedWorkOrders.add(wo.id);else selectedWorkOrders.delete(wo.id);
      renderWorkOrders();
    });
    const detail=document.createElement('div');detail.className='wo-card-main';
    const title=document.createElement('span');title.className='wo-card-title';
    title.textContent=safeLabel([wo.workOrderNumber,wo.siteName||wo.clientName||wo.description].filter(Boolean).join(' · ')||wo.id);
    const status=document.createElement('span');status.className='wo-status '+workOrderStatus(wo);
    status.textContent=workOrderStatus(wo).replace(/_/g,' ');
    const member=members.find(m=>m.uid===wo.assignedToUid);
    const subtitle=document.createElement('span');subtitle.className='wo-card-sub';
    const assignee=member?.displayName||member?.email||wo.assignedToEmail||'';
    subtitle.textContent=assignee?`Assigned to: ${assignee}`:'';
    const statusDate=document.createElement('span');statusDate.className='wo-card-status-date';
    statusDate.textContent=workOrderDisplayStatusDate(wo);
    detail.append(title,status);
    if(isWorkOrderOverdue(wo,today)){
      const overdueBadge=document.createElement('span');
      overdueBadge.className='wo-overdue-badge';overdueBadge.textContent='OVERDUE';
      detail.append(overdueBadge);
    }
    if(assignee)detail.append(subtitle);
    detail.append(statusDate);
    const quick=document.createElement('span');quick.className='fleet-wo-quick-meta';
    quick.textContent=workOrderPriority(wo)+' priority'+(workOrderDueDate(wo)?' · Due '+workOrderDueDate(wo):'');
    detail.append(quick);

    const extra=document.createElement('div');extra.className='wo-extra-meta';
    const appendMeta=(label,value,cssClass='')=>{
      const line=document.createElement('span');line.className=cssClass;
      line.textContent=`${label}: ${value}`;extra.append(line);
    };
    const dueDate=workOrderDueDate(wo);
    if(dueDate)appendMeta('Due date',dueDate,isWorkOrderOverdue(wo,today)?'wo-due-overdue':'');
    appendMeta('Priority',workOrderPriority(wo),workOrderPriority(wo)==='URGENT'?'wo-urgent':'');
    appendMeta('GPS route','Required');
    appendMeta('Photos',wo.isPhotoRequired===true?'Required':'Optional');
    if(workOrderStatus(wo)==='COMPLETED'&&String(wo.completionNotes||'').trim()){
      const notes=document.createElement('div');
      notes.className='wo-completion-notes';
      notes.textContent='Completion notes: '+String(wo.completionNotes).trim();
      extra.append(notes);
    }
    detail.append(extra);
    showWorkOrderRouteSummary(detail,wo);
    const wrap=document.createElement('div');wrap.className='wo-card-wrap';
    label.append(cb,detail);wrap.append(label);
    if(currentFleetIsAdmin && ['ASSIGNED','IN_PROGRESS'].includes(workOrderStatus(wo))){
      const cancelBtn=document.createElement('button');
      cancelBtn.type='button';cancelBtn.className='wo-cancel-action';
      cancelBtn.textContent='Cancel Work Order';
      cancelBtn.setAttribute('aria-label','Cancel Work Order '+String(wo.workOrderNumber||wo.id));
      cancelBtn.addEventListener('click',event=>{event.stopPropagation();openWebCancelWorkOrder(wo);});
      wrap.append(cancelBtn);
    }
    const actionRow=document.createElement('div');actionRow.className='fleet-wo-row-actions';
    const detailsButton=document.createElement('button');detailsButton.type='button';detailsButton.textContent='Details & map';
    detailsButton.addEventListener('click',()=>openWorkOrderEvidence(wo));
    const gps=document.createElement('button');gps.type='button';gps.textContent='GPS & photos';
    gps.addEventListener('click',()=>openWorkOrderEvidence(wo));
    const expand=document.createElement('button');expand.type='button';expand.textContent='Expand routes';
    expand.addEventListener('click',()=>{const expanded=wrap.classList.toggle('is-expanded');expand.textContent=expanded?'Hide routes':'Expand routes';});
    actionRow.append(gps,detailsButton,expand);
    appendCompletedWorkOrderPdfAction(actionRow,wo);
    wrap.append(actionRow);
    woList.append(wrap);
  }
  updateFleetCounts();
  woShowButton.disabled=!selectedWorkOrders.size||workOrderLoading;
  woShowButton.textContent=workOrderLoading?'Loading linked routes…':`Show selected Work Orders (${selectedWorkOrders.size})`;
  updateMapSelectionPrompt();
}
// The Work Orders screen shows GPS evidence and core job details at the same
// time. The existing full details drawer (including status history) remains
// available through the Details button; it no longer obscures the map on click.
function renderInlineWorkOrderDetails(wo){
  if(!fleetWorkspaceBuilt)return;
  const panel=document.getElementById('fleet-orders-selected-details');
  if(!panel)return;
  panel.replaceChildren();
  workOrderMapDetailId=wo?.id||null;
  panel.hidden=!wo;
  if(!wo)return;

  const heading=document.createElement('div');heading.className='fleet-wo-evidence-heading';
  const name=document.createElement('strong');name.className='fleet-wo-evidence-title';
  name.textContent=safeLabel(wo.workOrderNumber||wo.id);
  const status=document.createElement('span');status.className='wo-status fleet-wo-status-'+fleetWorkOrderColorStatus(workOrderStatus(wo));
  status.textContent=workOrderStatus(wo).replace(/_/g,' ')+(isWorkOrderOverdue(wo)?' · OVERDUE':'');
  const details=document.createElement('button');details.type='button';details.className='fleet-wo-evidence-more';
  details.textContent='Full details & history';
  details.addEventListener('click',()=>openFleetWorkOrderDetails(wo));
  heading.append(name,status,details);appendCompletedWorkOrderPdfAction(heading,wo);panel.append(heading);

  const facts=document.createElement('div');facts.className='fleet-wo-evidence-facts';
  const field=(label,value)=>{
    if(value==null||String(value).trim()==='')return;
    const entry=document.createElement('div');entry.className='fleet-wo-evidence-fact';
    const caption=document.createElement('small');caption.textContent=label;
    const text=document.createElement('span');text.textContent=String(value);
    entry.append(caption,text);facts.append(entry);
  };
  field('Site',wo.siteName||wo.clientName);
  const member=members.find(m=>m.uid===wo.assignedToUid);
  field('Assigned to',member?.displayName||member?.email||wo.assignedToEmail||'Unassigned');
  field('Due',workOrderDueDate(wo)||'No due date');
  field('Priority',workOrderPriority(wo));
  if(wo.siteName&&wo.clientName)field('Client',wo.clientName);
  panel.append(facts);
  if(wo.description){const description=document.createElement('p');description.className='fleet-wo-evidence-desc';description.textContent=String(wo.description);panel.append(description);}
  const routeStats=document.createElement('div');routeStats.id='fleet-orders-route-summary';routeStats.className='fleet-wo-evidence-routes';
  showWorkOrderRouteSummary(routeStats,wo);panel.append(routeStats);
}

function removeWorkOrderMapRoutes(){
  for(const id of [...workOrderRouteKeys])removeRouteSelection(id);
  workOrderRouteKeys.clear();
}
function leaveWorkOrderMapView(){
  ++workOrderLoadGeneration;
  workOrderLoading=false;
  removeWorkOrderMapRoutes();
  workOrderViewerActive=false;
  renderInlineWorkOrderDetails(null);
  routeOverviewActive=false;++routeOverviewToken;
  routePlaybackActive=false;routePlaybackOffset=0;routePlaybackLastProgress=0;routePlaybackEpoch=0;
  updateMapContextCaption();renderWorkOrders();updateRoutePlayButton();
  setWorkOrderFeedback("Shared routes selected. Select Work Orders and click Show to switch back.");
}
function resetWorkOrderPanel(){
  ++workOrderStatsGeneration;
  workOrderRouteStats.clear();
  ++workOrderLoadGeneration;
  if(workOrderUnsubscribe){workOrderUnsubscribe();workOrderUnsubscribe=null;}
  removeWorkOrderMapRoutes();
  workOrders=[];selectedWorkOrders.clear();workOrderLoading=false;workOrderViewerActive=false;
  workOrderDetailsOpenId=null;
  renderInlineWorkOrderDetails(null);
  workOrderCalendarSelectedDate='';workOrderCalendarUnscheduled=false;
  updateMapContextCaption();
  woPanel.hidden=true;woFilter.value='COMPLETED';woList.replaceChildren();setWorkOrderFeedback('');
  renderWorkOrders();
  renderFleetReports();
}
function observeAdminWorkOrders(authorizedFleetId){
  if(!authorizedFleetId||!db||!auth?.currentUser)return;
  if(workOrderUnsubscribe){workOrderUnsubscribe();workOrderUnsubscribe=null;}
  ++workOrderStatsGeneration;
  workOrderRouteStats.clear();
  const identity=auth.currentUser.uid;
  woPanel.hidden=false;
  woList.textContent='Loading Work Orders…';
  setWorkOrderFeedback('Click any Work Order to see its details, linked GPS routes and photos. Use checkboxes to compare multiple orders.');
  updateMapSelectionPrompt();
  workOrderUnsubscribe=onSnapshot(collection(db,'fleets',authorizedFleetId,'workOrders'),snap=>{
    if(auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
    workOrders=snap.docs.map(d=>({ ...d.data(),id:d.id})).sort((a,b)=>{
      if(workOrderStatus(a)==='COMPLETED'&&workOrderStatus(b)!=='COMPLETED')return 1;
      if(workOrderStatus(b)==='COMPLETED'&&workOrderStatus(a)!=='COMPLETED')return -1;
      return locationMillis(b.createdAt)-locationMillis(a.createdAt);
    });
    const known=new Set(workOrders.map(wo=>wo.id));
    if(workOrderDetailsOpenId&&!known.has(workOrderDetailsOpenId))closeFleetWorkOrderDetails();
    for(const id of [...selectedWorkOrders])if(!known.has(id))selectedWorkOrders.delete(id);
    for(const id of [...workOrderRouteStats.keys()])if(!known.has(id))workOrderRouteStats.delete(id);
    // Refresh changed Work Orders, including newly attached routes.
    for(const change of snap.docChanges()){
      if(change.type==='modified')workOrderRouteStats.delete(change.doc.id);
    }
    renderWorkOrders();
    renderFleetReports();
    if(workOrderMapDetailId){
      const selected=workOrders.find(wo=>wo.id===workOrderMapDetailId);
      renderInlineWorkOrderDetails(selected||null);
    }
    if(workOrderDetailsOpenId){
      const refreshed=workOrders.find(wo=>wo.id===workOrderDetailsOpenId);
      if(refreshed)openFleetWorkOrderDetails(refreshed);
    }
    scheduleWorkOrderRouteStats();
  },e=>{
    woList.textContent='Unable to load Work Orders.';
    setWorkOrderFeedback('Firestore Work Orders access failed: '+e.message,'error');
  });
}
// Convert the actual copied GPS/photo schema used by Work Order route attachments.
function normalizeWorkOrderLocation(data){
  const lat=Number(data.positionLatitude),lng=Number(data.positionLongitude);
  if(data.positionLatitude==null||data.positionLongitude==null||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)return null;
  return {lat,lng,ms:locationMillis(data.positionTimeMillis),counter:Number(data.positionCounter)||0};
}
async function loadWorkOrderRoute(workOrderId,routeDoc,authorizedFleetId,identity,generation){
  const routeId=routeDoc.id;
  const routeRef=doc(db,'fleets',authorizedFleetId,'workOrders',workOrderId,'routes',routeId);
  const [positionsSnapshot,photosSnapshot]=await Promise.all([
    getDocs(collection(routeRef,'locations')),
    getDocs(collection(routeRef,'photos'))
  ]);
  if(generation!==workOrderLoadGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return null;
  const points=positionsSnapshot.docs.map(d=>normalizeWorkOrderLocation(d.data())).filter(Boolean)
    .sort((a,b)=>(a.ms-b.ms)||(a.counter-b.counter))
    .map(({lat,lng})=>({lat,lng}));
  const photos=photosSnapshot.docs.map(d=>({id:d.id,...d.data()}));
  return {id:workOrderRouteKey(workOrderId,routeId),points,photos,orderId:workOrderId,routeId};
}
async function showSelectedWorkOrdersOnMap(){
  if(!db||!auth?.currentUser||!fleetId||workOrderLoading||!selectedWorkOrders.size)return;
  const identity=auth.currentUser.uid,authorizedFleetId=fleetId,generation=++workOrderLoadGeneration;
  workOrderLoading=true;renderWorkOrders();setWorkOrderFeedback('Loading GPS routes and photos from selected Work Orders…');
  const chosen=[...selectedWorkOrders];
  const failures=[];
  let skipped=0;
  const loaded=[];
  try{
    // Load the selected orders (with a small concurrency cap to protect large fleets).
    for(const orderId of chosen){
      if(generation!==workOrderLoadGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
      const orderRef=doc(db,'fleets',authorizedFleetId,'workOrders',orderId);
      let routeDocs;
      try{routeDocs=await getDocs(collection(orderRef,'routes'));}
      catch(e){failures.push(`${orderId}: ${e.message}`);continue;}
      const routeCandidates=routeDocs.docs.filter(d=>{
        const state=String(d.data().status||'READY').trim().toUpperCase();
        if(state==='READY'||state==='COMPLETED'||state==='SYNCED')return true;
        skipped++;return false;
      });
      for(let i=0;i<routeCandidates.length;i+=4){
        if(generation!==workOrderLoadGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
        const batch=await Promise.allSettled(routeCandidates.slice(i,i+4).map(d=>loadWorkOrderRoute(orderId,d,authorizedFleetId,identity,generation)));
        batch.forEach((result,index)=>{
          if(result.status==='fulfilled'&&result.value)loaded.push(result.value);
          else if(result.status==='rejected')failures.push(`${orderId}/${routeCandidates[i+index].id}: ${result.reason?.message||result.reason}`);
        });
      }
      setWorkOrderFeedback(`Loading Work Orders: ${loaded.length} routes found…`);
    }
    if(generation!==workOrderLoadGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
    // Remove previous Work Order overlays, but do not mutate Shared Routes documents.
    removeWorkOrderMapRoutes();
    // Defensive cleanup: the public demo must never appear in an authenticated map.
    removeRouteSelection(DEMO_ROUTE_ID);
    // Work Order map view replaces existing shared-route selection rather than mixing both views.
    for(const id of [...selectedRouteIds])if(!isWorkOrderRouteKey(id))removeRouteSelection(id);
    automaticRouteChosen=true;
    workOrderViewerActive=true;
    routePlaybackActive=false;routePlaybackOffset=0;routePlaybackLastProgress=0;routePlaybackEpoch=0;
    if(map && mapMode!=='satellite')await switchMapMode('satellite');
    if(generation!==workOrderLoadGeneration||auth.currentUser?.uid!==identity||fleetId!==authorizedFleetId)return;
    routeOverviewActive=true;
    for(const item of loaded){
      // Ignore empty routes rather than inventing GPS positions.
      if(!item.points.length){skipped++;continue;}
      const color=memberColor(item.id);
      workOrderRouteKeys.add(item.id);selectedRouteIds.add(item.id);
      routePointsById.set(item.id,item.points);routePhotosById.set(item.id,item.photos);
      routeLoadStates.set(item.id,{state:'loaded',message:`Work Order ${item.orderId} · ${item.points.length} GPS points · ${item.photos.length} photos`});
      if(map){
        const polyline=new maps.Polyline({map,path:displayRouteGeometry(item.points),strokeColor:color,strokeOpacity:1,strokeWeight:7,zIndex:35});
        routeOverlays.set(item.id,polyline);
        create2dRouteMarkers(item.id,item.points,color);
      }
    }
    renderPhotoMarkers();renderPhotoGallery();draw3dRoute();
    focusSelectedRoutes();updateRoutePlayButton();updateRouteSelectionInfo();updateRouteProgress();renderRoutes();
    // Google Maps may still have old dimensions just after moving its DOM node
    // from Shared History/Live into the Work Orders split view.
    requestAnimationFrame(()=>{
      if(generation!==workOrderLoadGeneration||fleetWorkspaceView!=='orders'||!workOrderViewerActive)return;
      resizeFleetMap();
      requestAnimationFrame(()=>{if(generation===workOrderLoadGeneration&&workOrderViewerActive)focusSelectedRoutes();});
    });
    const count=workOrderRouteKeys.size;
    const photoCount=[...workOrderRouteKeys].reduce((n,id)=>n+(routePhotosById.get(id)?.length||0),0);
    const mapPhotoCount=[...workOrderRouteKeys].reduce((n,id)=>n+(routePhotosById.get(id)||[]).filter(validPhotoCoords).length,0);
    setWorkOrderFeedback(count
      ?`Displaying ${count} GPS route${count===1?'':'s'} from ${chosen.length} selected Work Order${chosen.length===1?'':'s'}, with ${mapPhotoCount}/${photoCount} GPS photo marker${mapPhotoCount===1?'':'s'} on the map.${photoCount>mapPhotoCount?' Some photos have no GPS coordinates.':''}${skipped?' '+skipped+' incomplete/empty routes skipped.':''}${failures.length?' '+failures.length+' load errors.':''}`
      :`No completed GPS routes with points found in the selected Work Orders.${skipped?' '+skipped+' routes incomplete/empty.':''}${failures.length?' Errors: '+failures.slice(0,2).join('; '):''}`,count?'success':failures.length?'error':'');
    if(count)window.gtag?.('event','fleet_web_work_orders_routes_view',{work_order_count:chosen.length,route_count:count});
  }catch(e){
    if(generation===workOrderLoadGeneration)setWorkOrderFeedback('Could not display Work Orders: '+(e.message||e),'error');
  }finally{
    if(generation===workOrderLoadGeneration){workOrderLoading=false;renderWorkOrders();}
  }
}
// Single-click UX: the row opens the authenticated Work Order GPS evidence view.
// Existing checkboxes and "Show selected Work Orders" still support multi-order comparison.
function openWorkOrderEvidence(wo){
  if(!wo||!workOrders.some(item=>item.id===wo.id)||!workOrderMatchesMemberScope(wo)||woPanel.hidden)return;
  // Cancel a previous in-flight load when another Work Order is clicked.
  // Old async requests cannot overwrite the new selection (generation checks).
  ++workOrderLoadGeneration;
  workOrderLoading=false;
  if(workOrderViewerActive||workOrderRouteKeys.size){
    removeWorkOrderMapRoutes();
    workOrderViewerActive=false;
    updateMapContextCaption();
    renderPhotoMarkers();renderPhotoGallery();
  }
  selectedWorkOrders.clear();selectedWorkOrders.add(wo.id);
  closeFleetWorkOrderDetails();
  navigateFleetWorkspace('orders',{showMap:true});
  renderInlineWorkOrderDetails(wo);
  const mapTitle=document.getElementById('fleet-orders-map-title');
  if(mapTitle)mapTitle.textContent='GPS evidence · '+safeLabel(wo.workOrderNumber||wo.id);
  renderWorkOrders();
  // Draw linked routes immediately, without requiring a separate GPS button.
  showSelectedWorkOrdersOnMap();
}
