const DEMO_ROUTE_ID='__public_demo_route__';
const ROUTE_ZOOM_OUT_MS=3200;

// Work Order Reports — entirely client-side: no additional Firestore read or collection.
// Snapshot metrics are intentionally separate from the period-filtered activity trend.
function reportLocalDay(ms){
  if(!ms||!Number.isFinite(ms))return '';
  const d=new Date(ms);
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function reportWeekStart(date){
  const d=new Date(date.getFullYear(),date.getMonth(),date.getDate(),12);
  d.setDate(d.getDate()-((d.getDay()+6)%7));
  return d;
}
function reportWeekData(orders,numWeeks){
  const today=new Date();
  const start=reportWeekStart(today);
  start.setDate(start.getDate()-(numWeeks-1)*7);
  const result=Array.from({length:numWeeks},(_,i)=>{
    const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+7*i,12);
    return {start:reportLocalDay(d.getTime()),created:0,completed:0};
  });
  const index=new Map(result.map((v,i)=>[v.start,i]));
  function add(ms,field){
    if(!ms||!Number.isFinite(ms)||ms>Date.now()+86400000)return;
    const date=new Date(ms);
    const start=reportLocalDay(reportWeekStart(date).getTime());
    const i=index.get(start);
    if(i!==undefined)result[i][field]++;
  }
  for(const wo of orders){
    add(locationMillis(wo.createdAt??wo.createdAtMillis),'created');
    if(workOrderStatus(wo)==='COMPLETED'){
      // Completion date may be absent on legacy records — never guess using creation date.
      add(locationMillis(wo.completedAt??wo.completedAtMillis??wo.completionDate),'completed');
    }
  }
  return result;
}
function reportScopedOrders(){return workOrders.filter(workOrderMatchesMemberScope);}
function reportSummary(orders,today=workOrderLocalToday()){
  const open=orders.filter(wo=>['ASSIGNED','IN_PROGRESS'].includes(workOrderStatus(wo)));
  const overdue=open.filter(wo=>isWorkOrderOverdue(wo,today));
  const nextWeek=new Date(new Date(today+'T12:00:00').getTime());nextWeek.setDate(nextWeek.getDate()+7);
  const weekLimit=reportLocalDay(nextWeek.getTime());
  const dueSoon=open.filter(wo=>{const d=workOrderDueDate(wo);return !!d&&d>=today&&d<=weekLimit;});
  const completed=orders.filter(wo=>workOrderStatus(wo)==='COMPLETED');
  const evaluable=completed.filter(wo=>workOrderDueDate(wo)&&locationMillis(wo.completedAt??wo.completedAtMillis??wo.completionDate)>0);
  const onTime=evaluable.filter(wo=>reportLocalDay(locationMillis(wo.completedAt??wo.completedAtMillis??wo.completionDate))<=workOrderDueDate(wo)).length;
  return {open,overdue,dueSoon,completed,evaluable,onTime};
}
function reportNode(tag,className,textValue){
  const el=document.createElement(tag);
  if(className)el.className=className;
  if(textValue!==undefined)el.textContent=String(textValue);
  return el;
}
function reportStatusName(value){return ({ASSIGNED:'Assigned',IN_PROGRESS:'In progress',COMPLETED:'Completed',CREATED:'Created',REJECTED:'Rejected',CANCELLED:'Cancelled'})[value]||value;}
function renderFleetReports(){
  if(!fleetWorkspaceBuilt)return;
  const restricted=document.getElementById('fleet-reports-restricted');
  const dashboard=document.getElementById('fleet-reports-dashboard');
  if(!restricted||!dashboard)return;
  const allowed=!!currentFleetIsAdmin;
  restricted.hidden=allowed;dashboard.hidden=!allowed;
  document.getElementById('fleet-report-period').disabled=!allowed;
  document.getElementById('fleet-report-export').disabled=!allowed||!workOrders.length;
  if(!allowed)return;
  const orders=reportScopedOrders();
  const today=workOrderLocalToday();
  const s=reportSummary(orders,today);
  const member=members.find(m=>m.uid===fleetWorkspaceMemberScopeUid)||pendingMemberForScope();
  const scope=member?safeLabel(member.displayName||member.email||member.emailNormalized||member.uid||'Selected member'):'Entire fleet';
  document.getElementById('fleet-report-scope').textContent=`${scope} · ${orders.length} Work Orders · current as of ${today}`;
  const kpis=document.getElementById('fleet-report-kpis');kpis.replaceChildren();
  const cards=[
    {label:'Open now',value:s.open.length,detail:'Assigned + In progress',kind:'open'},
    {label:'Overdue now',value:s.overdue.length,detail:s.overdue.length?'Needs immediate attention':'No open orders past due',kind:'late'},
    {label:'Due next 7 days',value:s.dueSoon.length,detail:'Includes orders due today',kind:'soon'},
    {label:'On-time completion',value:s.evaluable.length?`${Math.round(100*s.onTime/s.evaluable.length)}%`:'—',detail:s.evaluable.length?`${s.onTime} of ${s.evaluable.length} completed with dated evidence`:'No completed jobs with both dates',kind:'ontime'}
  ];
  for(const c of cards){
    const card=reportNode('div','fleet-report-kpi is-'+c.kind);
    card.append(reportNode('span','fleet-report-kpi-label',c.label),reportNode('strong','fleet-report-kpi-value',c.value),reportNode('span','fleet-report-kpi-detail',c.detail));
    kpis.append(card);
  }
  const weeks=Math.max(8,Math.min(24,Number(document.getElementById('fleet-report-period').value)||12));
  const series=reportWeekData(orders,weeks);
  const max=Math.max(1,...series.flatMap(w=>[w.created,w.completed]));
  const chart=document.getElementById('fleet-report-chart');chart.replaceChildren();
  chart.style.setProperty('--report-weeks',String(weeks));
  chart.setAttribute('aria-label',series.map(w=>`${w.start}: ${w.created} created, ${w.completed} completed`).join('; '));
  for(const point of series){
    const col=reportNode('div','fleet-report-week');
    const bars=reportNode('div','fleet-report-bars');
    for(const [field,label] of [['created','Created'],['completed','Completed']]){
      const bar=reportNode('div','fleet-report-bar is-'+field);
      // Reserve a tiny visible bar for a count of 1; a count of 0 is empty.
      const pct=point[field]===0?0:Math.max(4,100*point[field]/max);
      bar.style.height=pct+'%';bar.title=`Week of ${point.start}: ${point[field]} ${label.toLowerCase()}`;
      bar.setAttribute('aria-label',bar.title);
      if(point[field]>0)bar.append(reportNode('span','fleet-report-bar-value',point[field]));
      bars.append(bar);
    }
    const label=reportNode('span','fleet-report-week-label',point.start.slice(5));
    col.append(bars,label);chart.append(col);
  }
  // On a narrow screen display the most recent weeks first, not the oldest weeks.
  const chartScroller=chart.parentElement;
  if(chartScroller)chartScroller.scrollLeft=chartScroller.scrollWidth-chartScroller.clientWidth;
  document.getElementById('fleet-report-chart-note').textContent=`${series.reduce((n,w)=>n+w.created,0)} created · ${series.reduce((n,w)=>n+w.completed,0)} completed in the last ${weeks} weeks. Historical completions missing completedAt are excluded.`;
  const distribution=new Map();
  const known=['ASSIGNED','IN_PROGRESS','COMPLETED','REJECTED','CANCELLED','CREATED'];
  for(const wo of orders){const st=workOrderStatus(wo);distribution.set(st,(distribution.get(st)||0)+1);}
  const statuses=[...known.filter(v=>distribution.has(v)),...[...distribution.keys()].filter(v=>!known.includes(v)).sort()];
  const statusBar=document.getElementById('fleet-report-status-bar');statusBar.replaceChildren();
  const statusList=document.getElementById('fleet-report-status-list');statusList.replaceChildren();
  for(const st of statuses){
    const count=distribution.get(st);
    const part=reportNode('div','fleet-report-status-segment fleet-wo-status-'+st);
    part.style.flex=String(count);
    part.title=`${reportStatusName(st)}: ${count}`;statusBar.append(part);
    const row=reportNode('div','fleet-report-status-row');
    const name=reportNode('span','fleet-report-status-name');
    name.append(reportNode('i','fleet-report-dot fleet-wo-status-'+st),reportNode('span','',reportStatusName(st)));
    row.append(name,reportNode('strong','',count));statusList.append(row);
  }
  if(!orders.length)statusList.append(reportNode('p','fleet-report-empty','No Work Orders in the selected scope.'));
  const urgent=[...s.overdue,...s.dueSoon].sort((a,b)=>{
    const ad=workOrderDueDate(a),bd=workOrderDueDate(b);
    if(ad!==bd)return ad.localeCompare(bd);
    const ranks={URGENT:0,HIGH:1,NORMAL:2,LOW:3};
    return ranks[workOrderPriority(a)]-ranks[workOrderPriority(b)];
  });
  document.getElementById('fleet-report-attention-count').textContent=urgent.length+' tasks';
  const risks=document.getElementById('fleet-report-risk-list');risks.replaceChildren();
  for(const wo of urgent.slice(0,30)){
    const late=isWorkOrderOverdue(wo,today);
    const btn=reportNode('button','fleet-report-risk-row'+(late?' is-overdue':''));
    btn.type='button';btn.title='Open Work Order details, GPS routes and photos';
    const a=reportNode('span','fleet-report-risk-summary');
    a.append(reportNode('strong','',wo.workOrderNumber||wo.id),reportNode('small','',wo.siteName||wo.clientName||wo.description||'No site details'));
    const meta=reportNode('span','fleet-report-risk-meta');
    meta.append(reportNode('span','fleet-report-risk-pill'+(late?' is-overdue':''),late?'Overdue':'Due soon'),reportNode('span','',workOrderDueDate(wo)),reportNode('span','',workOrderPriority(wo)));
    btn.append(a,meta);btn.addEventListener('click',()=>openWorkOrderEvidence(wo));risks.append(btn);
  }
  if(urgent.length>30)risks.append(reportNode('p','fleet-report-footnote',`Showing the first 30 of ${urgent.length} urgent deadlines.`));
  if(!urgent.length)risks.append(reportNode('p','fleet-report-empty','No overdue Work Orders or deadlines in the next 7 days.'));
}
function exportFleetWorkOrdersCsv(){
  if(!currentFleetIsAdmin||!fleetId)return;
  // Export the current member-scope selection, not hidden UI/search filters.
  const rows=reportScopedOrders().map(wo=>[
    wo.workOrderNumber||wo.id,wo.status||'ASSIGNED',wo.priority||'NORMAL',
    wo.assignedToEmail||'',wo.siteName||'',wo.clientName||'',wo.description||'',
    reportLocalDay(locationMillis(wo.createdAt??wo.createdAtMillis)),workOrderDueDate(wo),
    reportLocalDay(locationMillis(wo.completedAt??wo.completedAtMillis??wo.completionDate)),
    isWorkOrderOverdue(wo)?'YES':'NO',wo.isPhotoRequired===true?'YES':'NO'
  ]);
  const header=['Work Order','Status','Priority','Assignee email','Site','Client','Description','Created date','Due date','Completed date','Currently overdue','Photos required'];
  // Prevent CSV formula injection when opening user-entered data in spreadsheets.
  const csvField=value=>{
    let str=String(value??'').replace(/\r\n?/g,' ').replace(/\n/g,' ');
    if(/^[\s]*[=+@\-]/.test(str))str="'"+str;
    return '"'+str.replace(/"/g,'""')+'"';
  };
  const csv='\uFEFF'+[header,...rows].map(row=>row.map(csvField).join(';')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
  const link=document.createElement('a');link.href=url;
  link.download=`trackreporter-work-orders-${workOrderLocalToday()}.csv`;
  document.body.append(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}

